"""Mobile-first frontend served by the private job-search portal."""

PORTAL_HTML = r"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
  <meta name="theme-color" content="#071018">
  <title>Job Search Portal</title>
  <style>
    :root{color-scheme:dark;--bg:#071018;--panel:#0d1924;--panel2:#122536;--line:#233b4f;--text:#e9f2f8;--muted:#91a8ba;--blue:#65aefa;--green:#65d6ad;--amber:#f2cb84;--red:#ff9ca3;--shadow:0 16px 44px #0006}
    *{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 15% 0,#153047 0,var(--bg) 35%);color:var(--text);font:14px/1.45 Inter,system-ui,sans-serif}button,input,select,textarea{font:inherit}button,a,select{touch-action:manipulation}.hidden{display:none!important}
    button,.button{border:1px solid var(--line);border-radius:10px;background:transparent;color:var(--text);padding:9px 12px;cursor:pointer;text-decoration:none}button:hover,.button:hover{border-color:#42627c;background:#14293b}button.primary,.button.primary{border-color:#2e7ecf;background:#185a92;color:#fff}button.green{border-color:#3b9b78;color:var(--green)}button.danger{border-color:#8e454b;color:var(--red)}button:disabled{opacity:.55;cursor:wait}
    .shell{min-height:100dvh}.topbar{position:sticky;top:0;z-index:20;display:grid;grid-template-columns:auto minmax(260px,1fr) auto;align-items:center;gap:18px;padding:13px 20px;background:#091620ee;border-bottom:1px solid var(--line);backdrop-filter:blur(16px)}.brand small{display:block;color:var(--green);font-weight:800;letter-spacing:.15em;text-transform:uppercase}.brand strong{font-size:19px}.global-search{width:100%;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--text);padding:11px 14px;outline:none}.global-search:focus{border-color:var(--blue);box-shadow:0 0 0 3px #65aefa20}.header-actions{display:flex;gap:8px}
    .tabs{position:sticky;top:67px;z-index:19;display:flex;gap:5px;padding:7px 20px;background:#091620f2;border-bottom:1px solid var(--line);overflow-x:auto}.tab{white-space:nowrap;color:var(--muted);border-color:transparent}.tab.active{color:#071018;background:var(--blue);font-weight:800}.view{padding:16px 20px 28px}.toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:14px}.toolbar .spacer{flex:1}.muted{color:var(--muted)}.flash{min-height:21px;color:var(--muted)}.flash.error{color:var(--red)}
    .kanban{display:grid;grid-template-columns:repeat(5,minmax(260px,1fr));gap:11px;overflow-x:auto;padding-bottom:8px}.column{min-width:260px;background:#0b1721cc;border:1px solid var(--line);border-radius:14px;overflow:hidden}.column header{position:sticky;top:0;display:flex;justify-content:space-between;align-items:center;padding:11px;background:#102334;border-bottom:1px solid var(--line);font-weight:800}.column-list{display:grid;align-content:start;gap:9px;padding:9px;min-height:320px}.column.dragover{outline:2px solid var(--blue)}
    .job-card{background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:11px;box-shadow:0 7px 18px #0002}.job-card[draggable=true]{cursor:grab}.company{color:var(--green);font-size:11px;font-weight:850;letter-spacing:.05em;text-transform:uppercase}.role{font-size:14px;font-weight:780;margin:4px 0}.meta,.fit{display:flex;flex-wrap:wrap;gap:5px 9px;color:var(--muted);font-size:11px}.fit{color:#bed1df;margin-top:7px}.job-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}.job-actions button,.job-actions a{font-size:11px;padding:6px 8px}.status-select{max-width:145px;background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:6px}.mobile-list{display:none;gap:9px}.empty{padding:28px 12px;text-align:center;color:var(--muted)}
    .run-grid,.document-grid,.archive-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px}.archive-section{margin-top:18px;padding-top:12px;border-top:1px solid var(--line)}.archive-section h2{font-size:15px}.run-card,.document-card,.conversation-item{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:12px}.run-card{min-width:0;overflow-wrap:anywhere}.run-card details{margin-top:12px}.run-card details .run-card{margin-top:8px}.badge{display:inline-flex;border:1px solid var(--line);border-radius:999px;padding:2px 8px;font-size:11px}.badge.running,.badge.stopping,.badge.interviewing{color:var(--amber);border-color:#98783e}.badge.completed,.badge.offer{color:var(--green);border-color:#397b65}.badge.failed,.badge.rejected_employer{color:var(--red);border-color:#8e454b}.badge.applied{color:var(--blue);border-color:#346e9e}.run-events{max-height:55vh;overflow-y:auto;overflow-anchor:none;padding-right:4px}.run-event{font-size:12px;color:var(--muted);border-left:2px solid var(--line);padding-left:8px;margin:6px 0}.run-event.assistant_delta{white-space:pre-wrap;color:var(--text)}
    .chat-layout{display:grid;grid-template-columns:290px minmax(0,1fr);gap:12px;min-height:calc(100dvh - 170px)}.conversation-list{display:flex;flex-direction:column;gap:7px;overflow-y:auto}.conversation-item{text-align:left;width:100%}.conversation-item.active{border-color:var(--blue);background:#12283b}.chat-panel{display:flex;flex-direction:column;min-width:0;background:#0b1721cc;border:1px solid var(--line);border-radius:14px;overflow:hidden}.chat-head{display:flex;justify-content:space-between;align-items:center;padding:12px;border-bottom:1px solid var(--line)}.messages{flex:1;overflow-y:auto;padding:13px;min-height:300px}.message{max-width:min(780px,90%);white-space:pre-wrap;overflow-wrap:anywhere;border-radius:13px;padding:10px 12px;margin:8px 0}.message.user{margin-left:auto;background:#173d5d}.message.assistant{background:var(--panel2)}.message.streaming{border:1px solid #65aefa55}.composer{display:grid;grid-template-columns:1fr auto;gap:8px;padding:10px;border-top:1px solid var(--line)}.composer textarea{resize:none;min-height:48px;max-height:180px;border:1px solid var(--line);border-radius:11px;background:var(--panel);color:var(--text);padding:10px;outline:none}.activity{padding:8px 12px;color:var(--muted);font-size:12px;border-top:1px solid var(--line)}
    .document-card h3{font-size:13px;margin:0 0 6px}.document-actions{display:flex;gap:7px;margin-top:10px}.upload-input{display:none}.drawer{position:fixed;z-index:40;inset:0;display:flex;justify-content:flex-end;background:#0008}.drawer-panel{width:min(680px,100%);height:100%;overflow-y:auto;background:#0a1722;border-left:1px solid var(--line);box-shadow:var(--shadow);padding:18px}.drawer-head{display:flex;justify-content:space-between;gap:10px}.detail-section{border-top:1px solid var(--line);padding-top:14px;margin-top:14px}.detail-section h3{font-size:13px}.history-item{border-left:2px solid var(--line);padding:3px 0 8px 9px;margin:5px 0}.note-row{display:grid;grid-template-columns:1fr auto;gap:7px}.note-row input{background:var(--panel);border:1px solid var(--line);border-radius:9px;color:var(--text);padding:9px}.login{position:fixed;z-index:100;inset:0;display:grid;place-items:center;background:#071018}.login-card{width:min(390px,calc(100% - 28px));background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:var(--shadow)}.login-card input{width:100%;background:#071018;border:1px solid var(--line);border-radius:10px;color:var(--text);padding:11px;margin:10px 0}
    @media(min-width:821px){
      .shell.board-view,.shell.runs-view{height:100dvh;min-height:0;min-width:0;display:grid;grid-template-rows:auto auto minmax(0,1fr);overflow:hidden}
      .board-view>.topbar,.board-view>.tabs,.runs-view>.topbar,.runs-view>.tabs{position:static;min-width:0}
      .runs-view>#view-runs{display:flex;flex-direction:column;min-height:0;min-width:0;overflow:hidden}
      .runs-view .toolbar{flex-shrink:0}
      .runs-view #runs{flex:1;min-height:0;min-width:0;overflow-y:auto;overscroll-behavior-y:contain;scrollbar-gutter:stable;align-content:start;grid-auto-rows:max-content}
      .runs-view #runs:focus-visible{outline:2px solid var(--blue);outline-offset:-2px}
      .board-view>#view-jobs{display:flex;flex-direction:column;min-height:0;min-width:0;overflow:hidden}
      .board-view .toolbar,.board-view #flash{flex-shrink:0}
      .board-view .kanban{flex:1;min-height:0;min-width:0;grid-template-rows:minmax(0,1fr);overflow-y:hidden}
      .board-view .column{display:flex;flex-direction:column;min-height:0}
      .board-view .column>header{position:static;flex-shrink:0}
      .board-view .column-list{flex:1;min-height:0;overflow-y:auto;overscroll-behavior-y:contain;scrollbar-gutter:stable}
      .board-view .column-list:focus-visible{outline:2px solid var(--blue);outline-offset:-2px}
      .board-view .archive-section{min-height:0;max-height:30%;flex-shrink:1;overflow-y:auto}
    }
    @media(max-width:820px){.topbar{grid-template-columns:1fr auto;padding:10px 12px}.global-search{grid-column:1/-1;grid-row:2}.header-actions .wide{display:none}.tabs{top:108px;padding:6px 10px}.view{padding:12px}.kanban,.archive-section{display:none}.mobile-list{display:grid}.toolbar{align-items:stretch}.toolbar button{flex:1}.chat-layout{display:flex;flex-direction:column;min-height:calc(100dvh - 196px)}.conversation-list{flex-direction:row;overflow-x:auto;max-height:92px}.conversation-item{min-width:220px}.chat-panel{min-height:calc(100dvh - 290px)}.composer{grid-template-columns:1fr}.composer button{min-height:44px}.drawer-panel{border-left:0}.document-grid,.run-grid{grid-template-columns:1fr}.job-card{padding:12px}.status-select{min-height:38px}}
  </style>
</head>
<body>
<div id="login" class="login hidden"><form id="login-form" class="login-card"><small class="company">Private portal</small><h2>Sign in</h2><p class="muted">Enter the portal token configured on the server.</p><input id="login-token" type="password" autocomplete="current-password" required><button class="primary" type="submit">Sign in</button><p id="login-error" class="flash error"></p></form></div>
<main class="shell board-view">
  <header class="topbar"><div class="brand"><small>Private AI workspace</small><strong>Job Portal</strong></div><input id="search" class="global-search" type="search" placeholder="Search jobs, companies, statuses, CVs…"><div class="header-actions"><button id="refresh" title="Refresh">↻</button><button id="logout" class="wide hidden">Sign out</button></div></header>
  <nav class="tabs" aria-label="Portal sections"><button class="tab active" data-view="jobs">Jobs</button><button class="tab" data-view="runs">Runs</button><button class="tab" data-view="chat">Codex chat</button><button class="tab" data-view="documents">Application documents</button></nav>
  <section id="view-jobs" class="view"><div class="toolbar"><button id="search-jobs" class="primary">+ Search for new jobs</button><button id="generate-new-cvs" class="green" title="All recommended jobs in New, regardless of the search filter; ready and active CVs are skipped">Generate CVs for New</button><button id="refresh-all">↻ Refresh eligible</button><label class="muted"><input id="show-discoveries" type="checkbox"> Show discoveries</label><label class="muted"><input id="show-archive" type="checkbox"> Show rejected & withdrawn</label><span class="spacer"></span><span id="job-count" class="muted"></span></div><div id="flash" class="flash">Application pipeline · Qualified recommendations and tracked applications</div><div id="kanban" class="kanban"></div><div id="mobile-jobs" class="mobile-list"></div><section id="archive-section" class="archive-section hidden"><h2>Rejected & withdrawn archive</h2><div id="archive-jobs" class="archive-grid"></div></section></section>
  <section id="view-runs" class="view hidden"><div class="toolbar"><h2>Background runs</h2><span class="muted">Persistent after the browser closes</span><label><input id="show-archived-runs" type="checkbox"> Show archived</label><button id="stop-all-runs" class="danger" disabled>Stop all runs</button><button id="clear-runs" disabled>Clear run history</button><span id="runs-feedback" class="muted" role="status" aria-live="polite"></span></div><div id="runs" class="run-grid" tabindex="0" role="region" aria-label="Background run history"></div></section>
  <section id="view-chat" class="view hidden"><div class="toolbar"><button id="new-chat" class="primary">+ New conversation</button><button id="import-thread">Import CLI thread</button><select id="chat-job" class="status-select"><option value="">General project chat</option></select></div><div class="chat-layout"><aside id="conversations" class="conversation-list"></aside><section class="chat-panel"><header class="chat-head"><strong id="chat-title">Choose or create a conversation</strong><button id="stop-chat" class="danger hidden">Stop</button></header><div id="messages" class="messages"><div class="empty">Codex runs on the server and keeps working if you close this page.</div></div><div id="chat-activity" class="activity">Ready</div><form id="composer" class="composer"><textarea id="message" placeholder="Ask Codex about this project or selected job…" disabled></textarea><button class="primary" type="submit" disabled>Send</button></form></section></div></section>
  <section id="view-documents" class="view hidden"><div class="toolbar"><div><h2>Document library</h2><span class="muted">PDF and DOCX files stored in this private workspace</span></div><span class="spacer"></span><input id="upload-input" class="upload-input" type="file" accept=".pdf,.docx" multiple><button id="upload" class="green">Upload CV ↑</button></div><div id="documents" class="document-grid"></div><span class="hidden">Open or download without an embedded preview · CV ↓ · Mark applied · New updates · Suggested</span></section>
</main>
<div id="drawer" class="drawer hidden" role="dialog" aria-modal="true"><article id="drawer-panel" class="drawer-panel"></article></div>
<script>
const S={jobs:[],runs:[],documents:[],conversations:[],view:'jobs',query:'',archive:false,discoveries:false,conversation:null,conversationRequest:0,activeRun:null,runSubscriptions:new Map(),runCursors:new Map(),drawerRun:null,drawerUnsubscribe:null,drawerRefreshTimer:null,chatUnsubscribe:null,authenticated:false};
const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const statusLabels={new:'New',shortlisted:'Shortlisted',applied:'Applied',interviewing:'Interviewing',offer:'Offer',rejected_employer:'Rejected',withdrawn:'Withdrawn'};const boardStatuses=['new','shortlisted','applied','interviewing','offer'];
let boardDrag=null,pendingJobRender=false;
function cvControls(j){const cv=j.cv||{state:'not_generated'},active=['queued','generating'].includes(cv.state);const labels={not_generated:'Not generated',queued:'Queued',generating:'Generating',ready:'Ready',failed:'Failed'};const waiting=cv.waiting_for?`Waiting behind ${cv.waiting_for.task_type.replaceAll('_',' ')} · queue position ${cv.queue_position}`:cv.state==='queued'?`Queue position ${cv.queue_position||'pending'}`:'';return `<section class="cv-controls"><div class="fit">CV: ${esc(labels[cv.state]||cv.state)}${waiting?` · ${esc(waiting)}`:''}</div>${j.cv_file&&cv.state==='not_generated'?'<div class="muted" style="font-size:11px">Linked CV needs validation; Generate CV checks/reuses its PDF.</div>':''}${cv.progress||cv.error?`<div class="muted" style="font-size:11px;overflow-wrap:anywhere">${esc(cv.error||cv.progress)}</div>`:''}<div class="job-actions"><button class="green" data-cv-generate="${esc(j.id)}" ${active?'disabled':''}>Generate CV</button>${cv.url?`<a class="button primary" href="${esc(cv.url)}" target="_blank" rel="noopener">Open CV ↗</a><a class="button" href="${esc(cv.url)}?download=1">Download CV ↓</a>`:''}${cv.run_id?`<button data-run-details="${esc(cv.run_id)}">CV progress</button>`:''}${active?`<button class="danger" data-cv-cancel="${esc(cv.run_id)}">Cancel CV</button>`:''}${cv.state==='failed'&&cv.run_id?`<button data-cv-retry="${esc(cv.run_id)}">Retry CV</button>`:''}</div></section>`}
function bindCvControls(root){root.querySelectorAll('[data-cv-generate]').forEach(b=>b.onclick=()=>startJobRun(b.dataset.cvGenerate,'generate_cv',b));root.querySelectorAll('[data-cv-cancel]').forEach(b=>b.onclick=()=>cancelRun(b.dataset.cvCancel).then(loadJobs).catch(e=>flash(e.message,true)));root.querySelectorAll('[data-cv-retry]').forEach(b=>b.onclick=()=>retryRun(b.dataset.cvRetry).catch(e=>flash(e.message,true)));bindRunDetails(root)}
window.addEventListener('blur',stopBoardDrag);window.addEventListener('pagehide',stopBoardDrag);document.addEventListener('dragend',stopBoardDrag);document.addEventListener('drop',stopBoardDrag);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopBoardDrag()});
function stopBoardDrag(){if(boardDrag?.frame)cancelAnimationFrame(boardDrag.frame);boardDrag=null;document.querySelectorAll('.column.dragover').forEach(c=>c.classList.remove('dragover'));if(pendingJobRender){pendingJobRender=false;renderJobs()}}
function boardEdgeSpeed(position,start,end){const edge=Math.min(48,(end-start)/3);if(position<start||position>end||edge<=0)return 0;if(position<start+edge)return -600*(1-(position-start)/edge);if(position>end-edge)return 600*(1-(end-position)/edge);return 0}
function scrollBoardDrag(now){const drag=boardDrag;if(!drag)return;const elapsed=Math.min(50,now-(drag.lastTime??now))/1000;drag.lastTime=now;const board=$('kanban'),bounds=board.getBoundingClientRect();if(drag.y>=bounds.top&&drag.y<=bounds.bottom)board.scrollLeft+=boardEdgeSpeed(drag.x,bounds.left,bounds.right)*elapsed;if(drag.column?.isConnected){const list=drag.column.querySelector('.column-list'),rect=list.getBoundingClientRect();if(drag.x>=rect.left&&drag.x<=rect.right)list.scrollTop+=boardEdgeSpeed(drag.y,rect.top,rect.bottom)*elapsed}drag.frame=requestAnimationFrame(scrollBoardDrag)}
function startBoardDrag(e,card){stopBoardDrag();e.dataTransfer.setData('text/job-id',card.dataset.id);e.dataTransfer.effectAllowed='move';boardDrag={id:card.dataset.id,x:e.clientX,y:e.clientY,column:card.closest('.column'),frame:requestAnimationFrame(scrollBoardDrag)}}
function trackBoardDrag(e,column){if(!boardDrag)return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.column.dragover').forEach(c=>{if(c!==column)c.classList.remove('dragover')});column?.classList.add('dragover');boardDrag.x=e.clientX;boardDrag.y=e.clientY;boardDrag.column=column}
function key(){return crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`}
async function api(path,options={}){const headers={'X-Requested-With':'job-portal',...(options.headers||{})};if(options.body&&typeof options.body!=='string') {headers['Content-Type']='application/json';options.body=JSON.stringify(options.body)}const r=await fetch(path,{cache:'no-store',credentials:'same-origin',...options,headers});if(r.status===401){showLogin();throw new Error('Authentication required')}const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||`HTTP ${r.status}`);return data}
function showLogin(){S.authenticated=false;$('login').classList.remove('hidden')}function flash(msg,error=false){$('flash').textContent=msg;$('flash').classList.toggle('error',error)}function fmt(value){if(!value)return 'Not recorded';try{return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}catch{return value}}
async function session(){try{const x=await api('/api/session');S.authenticated=true;$('login').classList.add('hidden');$('logout').classList.toggle('hidden',!x.auth_enabled);await loadAll()}catch(e){}}
async function loadAll(){await Promise.all([loadJobs(),loadRuns(),loadDocuments(),loadConversations()])}
async function loadJobs(){const p=new URLSearchParams();if(S.archive)p.set('include_archived','1');if(S.discoveries)p.set('include_discoveries','1');if(S.query)p.set('q',S.query);const d=await api(`/api/jobs?${p}`);S.jobs=d.jobs;renderJobs();fillJobSelect()}
function jobPostingLink(j){return j.source_url?`<a class="button primary" data-job-posting="${esc(j.id)}" href="${esc(j.source_url)}" target="_blank" rel="noopener noreferrer">Open job posting ↗</a>`:'<span class="muted">Job posting link unavailable</span>'}
function card(j,mobile=false){const meta=[j.location||'Location unknown',j.work_arrangement||'Work arrangement unknown',j.qualification_status&&`Qualification: ${j.qualification_status.replaceAll('_',' ')}`,j.listing_status&&`Listing: ${j.listing_status}`,j.last_relevant_update&&`Updated ${fmt(j.last_relevant_update)}`].filter(Boolean);const fit=j.fit_score!=null?`${j.fit_score}/100 · ${j.fit_recommendation}`:j.fit_recommendation||'Not evaluated';return `<article class="job-card" data-id="${esc(j.id)}" draggable="${!mobile}"><div class="company">${esc(j.company)}</div><div class="role">${esc(j.title)}</div><div class="job-actions">${jobPostingLink(j)}</div><div class="meta">${meta.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="fit">${esc(fit)}${j.next_action?` · Next: ${esc(j.next_action)}`:''}</div>${cvControls(j)}<div class="job-actions"><button data-details="${esc(j.id)}">Details</button><select class="status-select" data-status="${esc(j.id)}" aria-label="Change status for ${esc(j.company)} ${esc(j.title)}">${Object.entries(statusLabels).map(([v,l])=>`<option value="${v}" ${v===j.application_status?'selected':''}>${l}</option>`).join('')}</select></div></article>`}
function renderJobs(){if(boardDrag){pendingJobRender=true;return}const board=$('kanban'),left=board.scrollLeft,positions=new Map([...board.querySelectorAll('[data-column]')].map(c=>[c.dataset.column,c.querySelector('.column-list').scrollTop]));const visible=S.jobs.filter(j=>!S.query||`${j.company} ${j.title} ${j.location} ${j.fit_recommendation} ${j.application_status}`.toLowerCase().includes(S.query.toLowerCase()));const archived=visible.filter(j=>['rejected_employer','withdrawn'].includes(j.application_status));$('job-count').textContent=`${visible.length} jobs`;$('kanban').innerHTML=boardStatuses.map(st=>{const jobs=visible.filter(j=>j.application_status===st);return `<section class="column" data-column="${st}"><header><span>${statusLabels[st]}</span><span class="badge ${st}">${jobs.length}</span></header><div class="column-list" tabindex="0" role="region" aria-label="${statusLabels[st]} jobs">${jobs.length?jobs.map(j=>card(j)).join(''):'<div class="empty">No jobs</div>'}</div></section>`}).join('');$('mobile-jobs').innerHTML=visible.length?visible.map(j=>card(j,true)).join(''):'<div class="empty">No jobs match.</div>';$('archive-section').classList.toggle('hidden',!S.archive||!archived.length);$('archive-jobs').innerHTML=archived.map(j=>card(j)).join('');board.scrollLeft=left;board.querySelectorAll('[data-column]').forEach(c=>c.querySelector('.column-list').scrollTop=positions.get(c.dataset.column)||0);bindJobControls()}
function bindJobControls(){bindCvControls(document);document.querySelectorAll('[data-details]').forEach(b=>b.onclick=()=>openJob(b.dataset.details));document.querySelectorAll('[data-status]').forEach(s=>s.onchange=()=>changeStatus(s.dataset.status,s.value,s));document.querySelectorAll('.job-card[draggable=true]').forEach(c=>{c.ondragstart=e=>startBoardDrag(e,c);c.ondragend=stopBoardDrag});const board=$('kanban');board.ondragover=e=>trackBoardDrag(e,e.target.closest('[data-column]'));board.ondragleave=e=>{if(boardDrag&&!board.contains(e.relatedTarget)){boardDrag.column=null;boardDrag.x=-1;document.querySelectorAll('.column.dragover').forEach(c=>c.classList.remove('dragover'))}};board.ondrop=e=>{e.preventDefault();const column=e.target.closest('[data-column]'),id=boardDrag?.id||e.dataTransfer.getData('text/job-id');stopBoardDrag();if(column&&S.jobs.some(j=>j.id===id))changeStatus(id,column.dataset.column)}}
async function changeStatus(id,status,select){const job=S.jobs.find(j=>j.id===id);const old=job?.application_status;if(job)job.application_status=status;renderJobs();try{await api(`/api/jobs/${id}/status`,{method:'POST',body:{status,idempotency_key:key(),expected_version:job?.version}});flash(`Moved to ${statusLabels[status]}`);await loadJobs()}catch(e){if(job)job.application_status=old;if(select)select.value=old;renderJobs();flash(e.message,true)}}
async function openJob(id){try{const j=await api(`/api/jobs/${id}`);const reasons=j.evaluation_reasons||{};const qualification=j.qualification_reasons||[];$('drawer-panel').innerHTML=`<div class="drawer-head"><div><div class="company">${esc(j.company)}</div><h2>${esc(j.title)}</h2></div><button id="close-drawer">✕</button></div><p class="muted">Stable ID: ${esc(j.id)}</p><div class="meta"><span>${esc(j.location||'Location unknown')}</span><span>${esc(j.work_arrangement||'Work arrangement unknown')}</span><span>Listing: ${esc(j.listing_status)}</span></div><div class="job-actions"><button data-run="refresh_listing">Refresh listing</button><button data-run="evaluate">Evaluate</button><button id="job-chat">Job chat</button>${jobPostingLink(j)}</div>${cvControls(j)}<section class="detail-section"><h3>Application</h3><select id="detail-status" class="status-select">${Object.entries(statusLabels).map(([v,l])=>`<option value="${v}" ${v===j.application_status?'selected':''}>${l}</option>`).join('')}</select><p>Last updated: ${esc(fmt(j.last_relevant_update))}<br>Last checked: ${esc(fmt(j.last_checked_at))}<br>Last evaluated: ${esc(fmt(j.last_evaluated_at))}</p></section><section class="detail-section"><h3>Qualification</h3><p><strong>${esc(j.qualification_status.replaceAll('_',' '))}</strong>${j.qualification_reviewed?' · Responsibilities reviewed':' · Awaiting responsibility review'}</p>${qualification.map(reason=>`<p>${esc(reason)}</p>`).join('')}</section><section class="detail-section"><h3>Evaluation</h3><p><strong>${j.fit_score??'—'}</strong> ${esc(j.fit_recommendation||'Not evaluated')}</p>${Object.entries(reasons).filter(([,v])=>v&&(!Array.isArray(v)||v.length)).map(([k,v])=>`<p><b>${esc(k.replaceAll('_',' '))}:</b> ${esc(Array.isArray(v)?v.join(' · '):v)}</p>`).join('')}</section><section class="detail-section"><h3>Artifacts</h3><div class="job-actions">${(j.artifacts||[]).map(a=>`<a class="button green" href="${esc(a.url)}?download=1">${esc(a.kind)} ↓</a>`).join('')||'<span class="muted">No linked artifacts</span>'}</div></section><section class="detail-section"><h3>Add note</h3><form id="note-form" class="note-row"><input id="note" maxlength="4000" required placeholder="Next action, recruiter update, interview note…"><button>Add</button></form></section><section class="detail-section"><h3>Status history & notes</h3>${(j.history||[]).map(h=>`<div class="history-item"><b>${esc(h.event_type.replaceAll('_',' '))}</b> ${h.old_value||h.new_value?`${esc(h.old_value||'')} → ${esc(h.new_value||'')}`:''}<br><span class="muted">${esc(fmt(h.created_at))} · ${esc(h.source)}</span>${h.note?`<div>${esc(h.note)}</div>`:''}</div>`).join('')||'<p class="muted">No history yet.</p>'}</section>`;bindCvControls($('drawer-panel'));$('drawer').classList.remove('hidden');$('close-drawer').onclick=closeDrawer;$('job-chat').onclick=()=>openJobChat(id);$('detail-status').onchange=e=>changeStatus(id,e.target.value,e.target);$('note-form').onsubmit=async e=>{e.preventDefault();try{await api(`/api/jobs/${id}/notes`,{method:'POST',body:{note:$('note').value,idempotency_key:key()}});await openJob(id);await loadJobs()}catch(x){flash(x.message,true)}};document.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>startJobRun(id,b.dataset.run,b))}catch(e){flash(e.message,true)}}
function stopDrawerWatch(){if(S.drawerUnsubscribe)S.drawerUnsubscribe();S.drawerUnsubscribe=null;S.drawerRun=null;if(S.drawerRefreshTimer)clearTimeout(S.drawerRefreshTimer);S.drawerRefreshTimer=null}
function closeDrawer(){stopDrawerWatch();$('drawer').classList.add('hidden')}
async function openJobChat(id){closeDrawer();showView('chat');await loadConversations();let conversation=S.conversations.find(c=>c.job_id===id);if(!conversation){const job=S.jobs.find(j=>j.id===id);const created=await api('/api/conversations',{method:'POST',body:{title:`Job chat · ${job?.company||'Job'}`,job_id:id}});conversation=created.conversation;await loadConversations()}await openConversation(conversation.id)}
async function startJobRun(id,type,button){button.disabled=true;try{const r=await api(`/api/jobs/${id}/${type==='refresh_listing'?'refresh':type==='generate_cv'?'generate-cv':'evaluate'}`,{method:'POST',body:{idempotency_key:key()}});flash(`${type.replaceAll('_',' ')} queued`);closeDrawer();await loadJobs();await loadRuns();if(type==='generate_cv'){await openRun(r.run.id)}else{showView('runs');watchRun(r.run.id)}}catch(e){flash(e.message,true)}finally{button.disabled=false}}
async function startSearch(){const focus=prompt('Optional focus (leave blank for all configured roles):','') ;if(focus===null)return;try{const r=await api('/api/searches',{method:'POST',body:{focus,idempotency_key:key()}});showView('runs');await loadRuns();watchRun(r.run.id)}catch(e){flash(e.message,true)}}
let refreshPreviewRequest=0,startingBatch=false,refreshSelection=new Set(),refreshPreview=null;
async function generateNewCvs(){const b=$('generate-new-cvs');if(b.disabled)return;b.disabled=true;b.textContent='Queueing CVs…';try{const d=await api('/api/cvs/generate-new',{method:'POST',body:{idempotency_key:key()}});flash(`${d.queued} CVs queued · ${d.ready} already ready · ${d.already_active} already queued/running${d.changed?' · '+d.changed+' left New':''}. CVs run up to ${d.concurrency??2} at a time; statuses unchanged.`);await loadJobs();await loadRuns()}catch(e){flash(e.message,true)}finally{b.disabled=false;b.textContent='Generate CVs for New'}}
async function refreshAll(){closeDrawer();$('drawer-panel').innerHTML=`<div class="drawer-head"><h2>Preview listing refresh</h2><button id="close-drawer">✕</button></div><p class="muted">Recommended New/Shortlisted only, stale after 24 hours by default. No evaluation or CV generation.</p><form id="refresh-preview-form"><div class="job-actions"><label>Freshness (hours) <input id="refresh-hours" type="number" min="1" max="8760" value="24" style="width:75px"></label><label>Batch size <input id="refresh-limit" type="number" min="1" max="100" value="10" style="width:65px"></label><label>Max AI fallbacks <input id="refresh-ai" type="number" min="0" max="20" value="2" style="width:65px"></label></div><p><label><input id="refresh-tracked" type="checkbox"> Include Applied/Interviewing for explicit selection</label></p><button type="submit">Update preview</button></form><p id="refresh-preview-count" role="status">Loading eligible jobs…</p><div id="refresh-preview-jobs"></div><div class="job-actions"><button id="start-refresh-batch" class="primary" disabled>Start selected batch</button></div><p id="refresh-preview-error" class="flash error"></p>`;$('drawer').classList.remove('hidden');$('close-drawer').onclick=closeDrawer;$('refresh-preview-form').onsubmit=e=>{e.preventDefault();loadRefreshPreview(false)};$('start-refresh-batch').onclick=submitRefreshBatch;await loadRefreshPreview(true)}
function refreshOptions(){return {freshness_hours:Number($('refresh-hours').value),limit:Number($('refresh-limit').value),max_ai_fallbacks:Number($('refresh-ai').value),include_tracked:$('refresh-tracked').checked}}
function refreshPreviewCount(){if(!$('refresh-preview-count'))return;$('refresh-preview-count').textContent=`${refreshPreview?.eligible_count||0} eligible · ${refreshSelection.size} selected (limit ${$('refresh-limit').value})`;$('start-refresh-batch').disabled=startingBatch||!refreshSelection.size||refreshSelection.size>Number($('refresh-limit').value)}
async function loadRefreshPreview(defaults=false){const request=++refreshPreviewRequest;try{const d=await api('/api/listings/refresh-preview',{method:'POST',body:defaults?{}:refreshOptions()});if(request!==refreshPreviewRequest||!$('refresh-preview-jobs'))return;refreshPreview=d;for(const [id,name] of [['refresh-hours','freshness_hours'],['refresh-limit','limit'],['refresh-ai','max_ai_fallbacks']])$(id).value=d.options[name];refreshSelection=new Set(d.jobs.filter(j=>['new','shortlisted'].includes(j.application_status)).slice(0,d.options.limit).map(j=>j.id));$('refresh-preview-jobs').innerHTML=d.jobs.map(j=>`<label class="history-item" style="display:block"><input type="checkbox" data-refresh-job="${esc(j.id)}" ${refreshSelection.has(j.id)?'checked':''}> ${esc(j.company)} — ${esc(j.title)}<br><span class="muted">${esc(statusLabels[j.application_status])} · Last checked ${esc(fmt(j.last_checked_at))}</span></label>`).join('')||'<p class="muted">No stale eligible jobs. Recently checked, closed, rejected, withdrawn, unqualified, or already active checks are excluded.</p>';$('refresh-preview-jobs').querySelectorAll('[data-refresh-job]').forEach(c=>c.onchange=()=>{c.checked?refreshSelection.add(c.dataset.refreshJob):refreshSelection.delete(c.dataset.refreshJob);refreshPreviewCount()});refreshPreviewCount();$('refresh-preview-error').textContent=''}catch(e){if($('refresh-preview-error'))$('refresh-preview-error').textContent=e.message}}
async function submitRefreshBatch(){if(startingBatch||!refreshSelection.size)return;startingBatch=true;refreshPreviewCount();try{const r=await api('/api/listings/refresh-eligible',{method:'POST',body:{...refreshOptions(),job_ids:[...refreshSelection],idempotency_key:key()}});closeDrawer();showView('runs');await loadRuns();await openRun(r.run.id)}catch(e){if($('refresh-preview-error'))$('refresh-preview-error').textContent=e.message;else flash(e.message,true)}finally{startingBatch=false;refreshPreviewCount()}}
let runsRequest=0,clearingRuns=false,runHistory={clearable:0,archived:0};
async function loadRuns(){const request=++runsRequest;const archived=$('show-archived-runs').checked;const d=await api('/api/runs'+(archived?'?include_archived=1':''));if(request!==runsRequest)return;S.runs=d.runs;runHistory=d.history||{clearable:0,archived:0};renderRuns()}
function bindRunDetails(root){root.querySelectorAll('[data-run-details]').forEach(b=>b.onclick=()=>openRun(b.dataset.runDetails))}
let stoppingRuns=false,stopPoll=null;
const expandedBatches=new Set();
function runLabel(r){return (r.cancel_requested&&['queued','running'].includes(r.state)?'Stopping':({queued:'Queued',running:'Running',stopping:'Stopping',cancelled:'Cancelled',interrupted:'Interrupted',completed:'Completed',failed:'Failed'}[r.display_state||r.state]||r.state))}
function usageMarkup(r){const u=r.usage||{},t=u.reported_tokens;const recorded=u.metrics_recorded??(u.deterministic_checks!=null||u.ai_fallbacks!=null||!!t);return `<p class="muted">${recorded?`Deterministic checks: ${u.deterministic_checks||0} · Cached: ${u.cache_hits||0} · AI fallbacks: ${u.ai_fallbacks||0} · Unresolved: ${u.unresolved||0}`:["queued","running"].includes(r.state)?"Checks not started":"Legacy check metrics not recorded"}<br>${t?`Actual reported tokens: ${esc(t.totalTokens)} (input ${esc(t.inputTokens)}, output ${esc(t.outputTokens)}, cached input ${esc(t.cachedInputTokens)}) · ${esc(u.usage_scope||"")}`:!recorded?"Tokens: not reported":u.ai_fallbacks?r.batch_id?"Tokens: see batch-level reporting":"Tokens: not reported":"Tokens: no AI used"} · No cost estimate</p>`}
function batchCounts(r){const c=r.counts||{};return `${c.completed||0}/${c.total||0} completed · ${c.queued||0} queued · ${c.running||0} running · ${c.stopping||0} stopping · ${c.cancelled||0} cancelled · ${c.interrupted||0} interrupted · ${c.failed||0} failed`}
function runCard(r,child=false){const active=['queued','running'].includes(r.state),batch=r.task_type==='refresh_bulk';const label=runLabel(r);const title=r.company?`${r.company} — ${r.job_title}`:r.task_type.replaceAll('_',' ');const summary=active?label:r.error||r.display_summary||r.result_summary||label;return `<article class="run-card" data-run-card="${esc(r.id)}"><div class="company">${esc(batch?'Refresh batch':r.task_type.replaceAll('_',' '))}</div><h3>${esc(title)}</h3><span class="badge ${esc(r.display_state||r.state)}">${esc(label)}</span>${r.archived_at?' <span class="badge">Archived</span>':''}<p class="muted">${esc(batch?batchCounts(r):summary)}</p>${['refresh_bulk','refresh_listing'].includes(r.task_type)?usageMarkup(r):''}<p class="muted">${esc(fmt(r.created_at))}</p><div class="job-actions"><button data-run-details="${esc(r.id)}">Progress</button>${batch&&((r.children||[]).some(c=>['queued','running'].includes(c.state))||active)?`<button class="danger" data-stop-batch="${esc(r.id)}" ${r.cancel_requested?'disabled':''}>${r.cancel_requested?'Stopping…':'Stop batch'}</button>`:active&&!batch?`<button class="danger" data-cancel="${esc(r.id)}" ${r.cancel_requested?'disabled':''}>${r.cancel_requested?'Stopping…':'Cancel'}</button>`:''}${(['failed','cancelled','interrupted'].includes(r.state)&&r.retry_allowed!==false&&!r.cancel_requested&&!child)?`<button data-retry="${esc(r.id)}">Retry</button>`:''}</div>${batch?`<details data-batch-expand="${esc(r.id)}" ${expandedBatches.has(r.id)?'open':''}><summary>Child checks (${r.children?.length||0})</summary>${(r.children||[]).map(c=>runCard(c,true)).join('')}</details>`:''}</article>`}
function renderRuns(){const list=$('runs'),top=list.scrollTop;list.querySelectorAll('[data-batch-expand]').forEach(d=>d.open?expandedBatches.add(d.dataset.batchExpand):expandedBatches.delete(d.dataset.batchExpand));const parents=new Set(S.runs.filter(r=>r.task_type==='refresh_bulk').map(r=>r.id));const visible=S.runs.filter(r=>!r.batch_id||!parents.has(r.batch_id));list.innerHTML=visible.length?visible.map(r=>runCard(r)).join(''):'<div class="empty">No visible runs. Enable Show archived to see cleared history.</div>';list.scrollTop=top;bindRunDetails(list);list.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>cancelRun(b.dataset.cancel));list.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>retryRun(b.dataset.retry));list.querySelectorAll('[data-stop-batch]').forEach(b=>b.onclick=()=>stopRuns(b.dataset.stopBatch,b));$('stop-all-runs').disabled=stoppingRuns||!S.runs.some(r=>['queued','running'].includes(r.state)&&!r.cancel_requested);$('clear-runs').disabled=clearingRuns||!runHistory.clearable;$('clear-runs').title=runHistory.clearable?`Archive ${runHistory.clearable} finished runs without deleting their data`:'No finished runs to clear'}
function stopFeedback(d){$('runs-feedback').textContent=`${d.state==='stopping'?'Stopping… ':''}${d.cancelled_queued} queued cancelled · ${d.interrupted_active} active interrupted · ${d.stopping} still stopping · ${d.failures.length} interrupt failures${d.finished_before_stop?' · '+d.finished_before_stop+' finished before stop':''}`}
async function stopRuns(batchId=null,button=null){if(stoppingRuns)return;stoppingRuns=true;if(button){button.disabled=true;button.textContent='Stopping…'}$('runs-feedback').textContent='Stopping…';$('stop-all-runs').disabled=true;try{const d=await api(batchId?`/api/runs/${batchId}/stop-batch`:'/api/runs/stop-all',{method:'POST',body:{idempotency_key:key()}});stopFeedback(d);await loadRuns();if(stopPoll)clearTimeout(stopPoll);const poll=async()=>{try{const latest=await api(`/api/stops/${d.id}`);stopFeedback(latest);await loadRuns();if(latest.state==='stopping')stopPoll=setTimeout(poll,700);else stopPoll=null}catch(e){$('runs-feedback').textContent='Unable to confirm stop: '+e.message}};if(d.state==='stopping')stopPoll=setTimeout(poll,300)}catch(e){$('runs-feedback').textContent='Failed to request stop: '+e.message}finally{stoppingRuns=false;renderRuns()}}
async function clearRunHistory(){if(clearingRuns||!runHistory.clearable)return;clearingRuns=true;renderRuns();$('runs-feedback').textContent='Clearing history…';try{const d=await api('/api/runs/archive-history',{method:'POST',body:{idempotency_key:key()}});$('runs-feedback').textContent=`${d.archived_count} run${d.archived_count===1?'':'s'} cleared. Logs and conversations retained.`;await loadRuns()}catch(e){$('runs-feedback').textContent=e.message}finally{clearingRuns=false;renderRuns()}}
function sortedRunEvents(events){return [...events].sort((a,b)=>Number(b.id)-Number(a.id))}
function runEventMarkup(e){return `<div class="run-event ${esc(e.kind)}" data-event-id="${Number(e.id)||0}"><b>${esc(e.kind)}</b> ${esc(e.message)}<br><span class="muted">${esc(fmt(e.created_at))}</span></div>`}
function captureRunLogScroll(log){if(!log)return null;const top=log.getBoundingClientRect().top;const anchor=[...log.children].find(e=>e.getBoundingClientRect().bottom>top);return {readingOlder:log.scrollTop>8,scrollTop:log.scrollTop,id:anchor?.dataset.eventId,offset:anchor?anchor.getBoundingClientRect().top-top:0}}
function restoreRunLogScroll(log,snapshot){if(!log||!snapshot)return;if(!snapshot.readingOlder){log.scrollTop=snapshot.scrollTop;return}const anchor=log.querySelector(`[data-event-id="${snapshot.id}"]`);if(anchor)log.scrollTop+=anchor.getBoundingClientRect().top-log.getBoundingClientRect().top-snapshot.offset;else log.scrollTop=snapshot.scrollTop}
function renderRunDrawer(r,preserveScroll=false){if(S.drawerRun!==r.id)return;const panel=$('drawer-panel');const oldPanelTop=panel.scrollTop;const oldLog=$('run-events');const logScroll=captureRunLogScroll(oldLog);panel.innerHTML=`<div class="drawer-head"><h2>${esc(r.task_type.replaceAll('_',' '))}</h2><button id="close-drawer">✕</button></div><p><span class="badge ${esc(r.state)}">${esc(runLabel(r))}</span></p>${r.state==='queued'?`<p class="muted">Queue position ${esc(r.queue_position||'pending')}${r.waiting_for?` · Waiting behind ${esc(r.waiting_for.task_type)}`:''}</p>`:''}${r.task_type==='refresh_bulk'?`<p>${esc(batchCounts(r))}</p>`:''}${['refresh_bulk','refresh_listing'].includes(r.task_type)?usageMarkup(r):''}<div class="job-actions">${['queued','running'].includes(r.state)?`<button id="cancel-drawer-run" class="danger">${r.cancel_requested?'Stopping…':r.task_type==='refresh_bulk'?'Stop batch':'Cancel task'}</button>`:''}${['failed','cancelled','interrupted'].includes(r.state)&&r.retry_allowed!==false?`<button id="retry-drawer-run">Retry task</button>`:''}</div>${r.error?`<p class="flash error">${esc(r.error)}</p>`:''}${r.result_summary?`<div class="detail-section"><h3>Result</h3><p>${esc(r.display_summary||r.result_summary)}</p></div>`:''}${r.artifacts?.length?`<div class="detail-section"><h3>Generated artifacts</h3><div class="job-actions">${r.artifacts.map(a=>`<a class="button green" href="${esc(a.url)}?download=1">${esc(a.kind||a.filename)} ↓</a>`).join('')}</div></div>`:''}<div id="run-events" class="run-events">${sortedRunEvents(r.events).map(runEventMarkup).join('')}</div>${r.approvals.filter(a=>a.state==='pending').map(a=>`<div class="detail-section"><h3>Approval required</h3><pre>${esc(JSON.stringify(a.params,null,2))}</pre><button data-approval="${a.id}" data-decision="approved">Approve once</button><button data-approval="${a.id}" data-decision="approved_for_session">Approve session</button><button class="danger" data-approval="${a.id}" data-decision="denied">Deny</button></div>`).join('')}`;$('drawer').classList.remove('hidden');if(preserveScroll){panel.scrollTop=oldPanelTop;restoreRunLogScroll($('run-events'),logScroll)}$('close-drawer').onclick=closeDrawer;if($('cancel-drawer-run'))$('cancel-drawer-run').onclick=async()=>{await cancelRun(r.id);await refreshRunDrawer(r.id)};if($('retry-drawer-run'))$('retry-drawer-run').onclick=()=>retryRun(r.id);document.querySelectorAll('[data-approval]').forEach(b=>b.onclick=async()=>{await api(`/api/approvals/${b.dataset.approval}`,{method:'POST',body:{decision:b.dataset.decision}});await refreshRunDrawer(r.id)})}
function prependRunEvent(event){const log=$('run-events');if(!log||!event||log.querySelector(`[data-event-id="${Number(event.id)||0}"]`))return;const snapshot=captureRunLogScroll(log);const next=[...log.children].find(e=>Number(e.dataset.eventId)<Number(event.id));if(next)next.insertAdjacentHTML('beforebegin',runEventMarkup(event));else log.insertAdjacentHTML('beforeend',runEventMarkup(event));restoreRunLogScroll(log,snapshot)}
async function refreshRunDrawer(id){if(S.drawerRun!==id)return;const r=await api(`/api/runs/${id}`);if(S.drawerRun===id)renderRunDrawer(r,true);if(!['queued','running'].includes(r.state)&&S.drawerUnsubscribe){S.drawerUnsubscribe();S.drawerUnsubscribe=null}}
function scheduleRunDrawerRefresh(id){if(S.drawerRun!==id||S.drawerRefreshTimer)return;S.drawerRefreshTimer=setTimeout(async()=>{S.drawerRefreshTimer=null;try{await refreshRunDrawer(id)}catch(e){flash(e.message,true)}},120)}
async function openRun(id){stopDrawerWatch();S.drawerRun=id;const r=await api(`/api/runs/${id}`);if(S.drawerRun!==id)return;renderRunDrawer(r);if(['queued','running'].includes(r.state))S.drawerUnsubscribe=watchRun(id,payload=>{if(payload.event)prependRunEvent(payload.event);if(payload.terminal||['approval_required','running'].includes(payload.event?.kind))scheduleRunDrawerRefresh(id)})}
async function cancelRun(id){await api(`/api/runs/${id}/cancel`,{method:'POST',body:{}});await loadRuns();await loadJobs()}async function retryRun(id){const r=await api(`/api/runs/${id}/retry`,{method:'POST',body:{idempotency_key:key()}});await loadRuns();await loadJobs();await openRun(r.run.id)}
function closeRunSubscription(sub){if(sub.source)sub.source.close();sub.source=null;if(sub.timer)clearTimeout(sub.timer);sub.timer=null;sub.polling=false;S.runSubscriptions.delete(sub.id)}
function deliverRunUpdate(sub,payload,eventId=0){if(eventId>sub.cursor){sub.cursor=eventId;S.runCursors.set(sub.id,eventId)}for(const listener of [...sub.listeners])Promise.resolve(listener(payload)).catch(error=>console.error(error));if(payload.terminal){closeRunSubscription(sub);Promise.all([loadRuns(),loadJobs(),loadDocuments(),loadConversations()]).catch(error=>console.error(error))}}
function connectRunSubscription(sub){if(S.runSubscriptions.get(sub.id)!==sub||sub.source||sub.timer)return;const after=Math.max(sub.cursor,S.runCursors.get(sub.id)||0);const es=new EventSource(`/api/runs/${sub.id}/events?after=${after}`);sub.source=es;es.onmessage=e=>{if(S.runSubscriptions.get(sub.id)!==sub)return;let payload;try{payload=JSON.parse(e.data)}catch{return}deliverRunUpdate(sub,payload,Number(e.lastEventId||0))};es.onerror=()=>{if(S.runSubscriptions.get(sub.id)!==sub)return;es.close();sub.source=null;pollRunSubscription(sub)}}
async function pollRunSubscription(sub){if(S.runSubscriptions.get(sub.id)!==sub||sub.polling)return;sub.polling=true;try{const run=await api(`/api/runs/${sub.id}`);for(const event of run.events.filter(event=>Number(event.id)>sub.cursor)){deliverRunUpdate(sub,{event,terminal:false},Number(event.id));if(S.runSubscriptions.get(sub.id)!==sub)return}if(['completed','failed','cancelled','interrupted'].includes(run.state)){deliverRunUpdate(sub,{terminal:true,state:run.state,run});return}}catch(e){console.error(e)}finally{sub.polling=false}if(S.runSubscriptions.get(sub.id)===sub)sub.timer=setTimeout(()=>{sub.timer=null;connectRunSubscription(sub)},1500)}
function subscribeRun(id,listener){let sub=S.runSubscriptions.get(id);if(!sub){sub={id,cursor:S.runCursors.get(id)||0,source:null,timer:null,polling:false,listeners:new Set()};S.runSubscriptions.set(id,sub)}sub.listeners.add(listener);connectRunSubscription(sub);return()=>{sub.listeners.delete(listener);if(!sub.listeners.size&&S.runSubscriptions.get(id)===sub)closeRunSubscription(sub)}}
function watchRun(id,onEvent=()=>{}){return subscribeRun(id,onEvent)}
async function loadDocuments(){const d=await api('/api/documents');S.documents=d.documents;$('documents').innerHTML=S.documents.length?S.documents.filter(d=>!S.query||`${d.title} ${d.filename}`.toLowerCase().includes(S.query.toLowerCase())).map(d=>`<article class="document-card"><div class="company">${esc(d.kind_label)} · ${esc(d.format)}</div><h3>${esc(d.title)}</h3><span class="muted">${esc(d.filename)}</span><div class="document-actions"><a class="button primary" href="${esc(d.url)}" target="_blank">Open ↗</a><a class="button" href="${esc(d.url)}?download=1">Download ↓</a></div></article>`).join(''):'<div class="empty">No CV documents found.</div>'}
async function upload(files){for(const file of files){const r=await fetch('/api/cv/upload',{method:'POST',credentials:'same-origin',headers:{'Content-Type':file.type||'application/octet-stream','X-Filename':encodeURIComponent(file.name),'X-Requested-With':'job-portal'},body:file});const d=await r.json();if(!r.ok)throw new Error(d.error||`Upload failed`)}await loadDocuments()}
async function loadConversations(){const d=await api('/api/conversations');S.conversations=d.conversations;renderConversations()}
function renderConversations(){$('conversations').innerHTML=S.conversations.length?S.conversations.map(c=>`<button class="conversation-item ${S.conversation===c.id?'active':''}" data-conversation="${c.id}"><b>${esc(c.title)}</b><br><span class="muted">${esc(c.company?`${c.company} · ${c.job_title}`:'General')} · ${esc(fmt(c.updated_at))}</span></button>`).join(''):'<div class="empty">No conversations yet.</div>';document.querySelectorAll('[data-conversation]').forEach(b=>b.onclick=()=>openConversation(b.dataset.conversation))}
function stopChatWatch(){if(S.chatUnsubscribe)S.chatUnsubscribe();S.chatUnsubscribe=null}
function renderConversationMessages(c){$('chat-title').textContent=c.title;$('messages').innerHTML=c.messages.length?c.messages.map(m=>`<div class="message ${esc(m.role)}">${esc(m.content)}${(m.cv_runs||[]).map(r=>`<div class="job-actions"><button data-run-details="${esc(r.id)}">CV progress · ${esc(r.company)} · ${esc(r.title)}</button></div>`).join('')}${m.run_id?`<div class="job-actions"><button data-run-details="${esc(m.run_id)}">Run details</button></div>`:''}</div>`).join(''):'<div class="empty">Start the conversation below.</div>';bindRunDetails($('messages'));$('messages').scrollTop=$('messages').scrollHeight;$('message').disabled=false;$('composer').querySelector('button').disabled=false}
async function refreshConversationMessages(id){const c=await api(`/api/conversations/${id}`);if(S.conversation!==id)return;renderConversationMessages(c);renderConversations()}
function appendChatDelta(conversationId,runId,delta){if(S.conversation!==conversationId||S.activeRun!==runId)return;let draft=document.querySelector(`[data-chat-run="${runId}"]`);if(!draft){const empty=$('messages').querySelector('.empty');if(empty)empty.remove();draft=document.createElement('div');draft.className='message assistant streaming';draft.dataset.chatRun=runId;$('messages').appendChild(draft)}draft.textContent+=delta;$('messages').scrollTop=$('messages').scrollHeight;$('chat-activity').textContent='Codex is responding…'}
async function watchChat(runId,conversationId){stopChatWatch();const run=await api(`/api/runs/${runId}`);if(S.conversation!==conversationId||S.activeRun!==runId)return;const deltas=run.events.filter(event=>event.kind==='assistant_delta').map(event=>event.message).join('');if(deltas)appendChatDelta(conversationId,runId,deltas);const lastEvent=Math.max(0,...run.events.map(event=>Number(event.id)||0));S.runCursors.set(runId,lastEvent);const existingSubscription=S.runSubscriptions.get(runId);if(existingSubscription)existingSubscription.cursor=Math.max(existingSubscription.cursor,lastEvent);$('chat-activity').textContent=run.state==='queued'?`Queued${run.waiting_for?' behind '+run.waiting_for.task_type:''} · position ${run.queue_position||'pending'}`:'Working…';if(!['queued','running'].includes(run.state)){S.activeRun=null;$('stop-chat').classList.add('hidden');$('chat-activity').textContent=run.state;await refreshConversationMessages(conversationId);return}S.chatUnsubscribe=watchRun(runId,async payload=>{if(S.conversation!==conversationId||S.activeRun!==runId)return;if(payload.event&&['activity','cv_progress','command_output'].includes(payload.event.kind))$('chat-activity').textContent=payload.event.message.slice(0,200);if(payload.event?.kind==='assistant_delta')appendChatDelta(conversationId,runId,payload.event.message||'');if(payload.terminal){S.activeRun=null;$('stop-chat').classList.add('hidden');$('chat-activity').textContent=payload.state;stopChatWatch();await openConversation(conversationId)}})}
async function openConversation(id){stopChatWatch();const request=++S.conversationRequest;S.conversation=id;const [c,runs]=await Promise.all([api(`/api/conversations/${id}`),api('/api/runs')]);if(request!==S.conversationRequest||S.conversation!==id)return;renderConversationMessages(c);renderConversations();const linked=new Set(c.messages.flatMap(m=>(m.cv_runs||[]).map(r=>r.id)));const active=runs.runs.find(r=>(r.conversation_id===id||linked.has(r.id))&&['queued','running'].includes(r.state));S.activeRun=active?.id||null;$('stop-chat').classList.toggle('hidden',!active);$('chat-activity').textContent=active?'Reconnecting to Codex…':'Ready';if(active)await watchChat(active.id,id)}
async function newChat(){const job=$('chat-job').value;const title=job?`Job chat · ${S.jobs.find(j=>j.id===job)?.company||'Job'}`:'General project chat';const c=await api('/api/conversations',{method:'POST',body:{title,job_id:job||null}});await loadConversations();await openConversation(c.conversation.id)}
async function sendMessage(e){e.preventDefault();const text=$('message').value.trim();const conversationId=S.conversation;if(!text||!conversationId)return;$('message').value='';const r=await api(`/api/conversations/${conversationId}/messages`,{method:'POST',body:{message:text,idempotency_key:key()}});if(S.conversation!==conversationId)return;S.activeRun=r.run.id;$('stop-chat').classList.remove('hidden');await openConversation(conversationId)}
async function importThread(){const d=await api('/api/codex/threads');const choices=d.threads.slice(0,10).map((t,i)=>`${i+1}. ${t.preview||t.id} [${t.id}]`).join('\n');const selected=prompt(`Enter a number to import:\n${choices}`,'1');if(!selected)return;const t=d.threads[Number(selected)-1];if(!t)return alert('Invalid selection');const c=await api('/api/conversations/import',{method:'POST',body:{thread_id:t.id,title:t.preview||'Imported Codex conversation'}});await loadConversations();await openConversation(c.conversation.id)}
function fillJobSelect(){const current=$('chat-job').value;$('chat-job').innerHTML='<option value="">General project chat</option>'+S.jobs.map(j=>`<option value="${j.id}">${esc(j.company)} · ${esc(j.title)}</option>`).join('');$('chat-job').value=current}
function showView(view){stopBoardDrag();S.view=view;document.querySelector('.shell').classList.toggle('board-view',view==='jobs');document.querySelector('.shell').classList.toggle('runs-view',view==='runs');document.querySelectorAll('.view').forEach(v=>v.classList.add('hidden'));$(`view-${view}`).classList.remove('hidden');document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.view===view));if(view==='runs')loadRuns();if(view==='chat')loadConversations();if(view==='documents')loadDocuments()}
$('show-archived-runs').onchange=()=>loadRuns().catch(e=>{$('runs-feedback').textContent=e.message});$('clear-runs').onclick=clearRunHistory;
$('stop-all-runs').onclick=()=>stopRuns();
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>showView(t.dataset.view));$('search').oninput=e=>{S.query=e.target.value;if(S.view==='jobs')loadJobs();if(S.view==='documents')loadDocuments()};$('show-discoveries').onchange=e=>{S.discoveries=e.target.checked;loadJobs()};$('show-archive').onchange=e=>{S.archive=e.target.checked;loadJobs()};$('search-jobs').onclick=startSearch;$('refresh-all').onclick=refreshAll;$('generate-new-cvs').onclick=generateNewCvs;$('refresh').onclick=loadAll;$('drawer').onclick=e=>{if(e.target===$('drawer'))closeDrawer()};$('new-chat').onclick=newChat;$('import-thread').onclick=importThread;$('composer').onsubmit=sendMessage;$('stop-chat').onclick=()=>S.activeRun&&cancelRun(S.activeRun);$('upload').onclick=()=>$('upload-input').click();$('upload-input').onchange=async e=>{try{await upload([...e.target.files]);e.target.value=''}catch(x){flash(x.message,true)}};$('login-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/auth/login',{method:'POST',body:{token:$('login-token').value}});$('login-token').value='';await session()}catch(x){$('login-error').textContent=x.message}};$('logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST',body:{}});showLogin()};session();setInterval(()=>{if(S.authenticated){loadRuns();if(S.view==='jobs')loadJobs()}},10000);
</script>
</body></html>"""
